script:
test("six payments within nine minutes raise an alert at the sixth payment", function () {
  assert.deepEqual(code.checkCardPayments({ paymentTimes: ["2024-06-15T10:00:00Z", "2024-06-15T10:02:00Z", "2024-06-15T10:04:00Z", "2024-06-15T10:06:00Z", "2024-06-15T10:08:00Z", "2024-06-15T10:09:00Z"] }), { alert: true, alertTime: "2024-06-15T10:09:00Z" });
});

test("payments exactly ten minutes apart raise no alert", function () {
  assert.deepEqual(code.checkCardPayments({ paymentTimes: ["2024-06-15T10:00:00Z", "2024-06-15T10:02:00Z", "2024-06-15T10:04:00Z", "2024-06-15T10:06:00Z", "2024-06-15T10:08:00Z", "2024-06-15T10:10:00Z"] }), { alert: false, alertTime: null });
});

test("exactly five payments raise no alert", function () {
  assert.deepEqual(code.checkCardPayments({ paymentTimes: ["2024-06-15T10:00:00Z", "2024-06-15T10:02:00Z", "2024-06-15T10:04:00Z", "2024-06-15T10:06:00Z", "2024-06-15T10:08:00Z"] }), { alert: false, alertTime: null });
});

test("four payments within ten minutes raise no alert", function () {
  assert.deepEqual(code.checkCardPayments({ paymentTimes: ["2024-06-15T11:00:00Z", "2024-06-15T11:01:00Z", "2024-06-15T11:02:00Z", "2024-06-15T11:03:00Z"] }), { alert: false, alertTime: null });
});

test("an empty payment list raises no alert", function () {
  assert.deepEqual(code.checkCardPayments({ paymentTimes: [] }), { alert: false, alertTime: null });
});

test("a single payment raises no alert", function () {
  assert.deepEqual(code.checkCardPayments({ paymentTimes: ["2024-06-15T10:00:00Z"] }), { alert: false, alertTime: null });
});

test("six payments one second under ten minutes raise an alert at the sixth payment", function () {
  assert.deepEqual(code.checkCardPayments({ paymentTimes: ["2024-06-15T10:00:00Z", "2024-06-15T10:02:00Z", "2024-06-15T10:04:00Z", "2024-06-15T10:06:00Z", "2024-06-15T10:08:00Z", "2024-06-15T10:09:59Z"] }), { alert: true, alertTime: "2024-06-15T10:09:59Z" });
});

test("a sixth payment one second over ten minutes raises no alert", function () {
  assert.deepEqual(code.checkCardPayments({ paymentTimes: ["2024-06-15T10:00:00Z", "2024-06-15T10:02:00Z", "2024-06-15T10:04:00Z", "2024-06-15T10:06:00Z", "2024-06-15T10:08:00Z", "2024-06-15T10:10:01Z"] }), { alert: false, alertTime: null });
});

test("a window that starts in the middle raises an alert at the last payment", function () {
  assert.deepEqual(code.checkCardPayments({ paymentTimes: ["2024-06-15T09:00:00Z", "2024-06-15T10:00:00Z", "2024-06-15T10:01:00Z", "2024-06-15T10:02:00Z", "2024-06-15T10:03:00Z", "2024-06-15T10:04:00Z", "2024-06-15T10:05:00Z"] }), { alert: true, alertTime: "2024-06-15T10:05:00Z" });
});

test("the payment that causes the alert in the middle is returned", function () {
  assert.deepEqual(code.checkCardPayments({ paymentTimes: ["2024-06-15T14:00:00Z", "2024-06-15T14:01:00Z", "2024-06-15T14:02:00Z", "2024-06-15T14:03:00Z", "2024-06-15T14:04:00Z", "2024-06-15T14:05:00Z", "2024-06-15T14:20:00Z", "2024-06-15T14:40:00Z", "2024-06-15T15:00:00Z", "2024-06-15T15:20:00Z", "2024-06-15T15:40:00Z"] }), { alert: true, alertTime: "2024-06-15T14:05:00Z" });
});

test("six payments not aligned to the hour raise an alert at the sixth payment", function () {
  assert.deepEqual(code.checkCardPayments({ paymentTimes: ["2024-06-15T10:06:00Z", "2024-06-15T10:07:00Z", "2024-06-15T10:08:00Z", "2024-06-15T10:09:00Z", "2024-06-15T10:10:00Z", "2024-06-15T10:11:00Z"] }), { alert: true, alertTime: "2024-06-15T10:11:00Z" });
});

test("six payments across the last day of a month raise an alert at the sixth payment", function () {
  assert.deepEqual(code.checkCardPayments({ paymentTimes: ["2024-01-31T23:56:00Z", "2024-01-31T23:57:00Z", "2024-01-31T23:58:00Z", "2024-01-31T23:59:00Z", "2024-02-01T00:00:00Z", "2024-02-01T00:04:00Z"] }), { alert: true, alertTime: "2024-02-01T00:04:00Z" });
});

test("six payments across a year change raise an alert at the sixth payment", function () {
  assert.deepEqual(code.checkCardPayments({ paymentTimes: ["2024-12-31T23:55:00Z", "2024-12-31T23:56:00Z", "2024-12-31T23:57:00Z", "2024-12-31T23:58:00Z", "2025-01-01T00:00:00Z", "2025-01-01T00:04:00Z"] }), { alert: true, alertTime: "2025-01-01T00:04:00Z" });
});

test("six payments across leap day raise an alert at the sixth payment", function () {
  assert.deepEqual(code.checkCardPayments({ paymentTimes: ["2024-02-29T23:56:00Z", "2024-02-29T23:57:00Z", "2024-02-29T23:58:00Z", "2024-02-29T23:59:00Z", "2024-03-01T00:00:00Z", "2024-03-01T00:03:00Z"] }), { alert: true, alertTime: "2024-03-01T00:03:00Z" });
});

test("an unknown field throws an error naming that field", function () {
  assert.throws(function () {
    code.checkCardPayments({ paymentTimes: ["2024-06-15T10:00:00Z"], accountId: "a1" });
  }, /unknown field: accountId/);
});
